    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(0, 1, 2, 3, 4))
    namedValues = NamedValues(("notSignificant", 0), ("clearSlot", 1), ("clearSlotImmediately", 2), ("reloadAny", 3), ("reloadPassThru", 4))

